export type StockVaultPluginPdas = {
  usdcVault: typeof findUsdcVaultPda;
  config: typeof findConfigPda;
  position: typeof findPositionPda;
  market: typeof findMarketPda;
  collateralVault: typeof findCollateralVaultPda;
  supplier: typeof findSupplierPda;
};

export type StockVaultPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function stockVaultProgram() {
  return <T extends StockVaultPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { stockVault: StockVaultPlugin }> => {
    return extendClient(client, {
      stockVault: {
        accounts: {
          liquidationRecord: addSelfFetchFunctions(
            client,
            getLiquidationRecordCodec(),
          ),
          market: addSelfFetchFunctions(client, getMarketCodec()),
          position: addSelfFetchFunctions(client, getPositionCodec()),
          supplier: addSelfFetchFunctions(client, getSupplierCodec()),
          vaultConfig: addSelfFetchFunctions(client, getVaultConfigCodec()),
        },
        instructions: {
          absorbBadDebtCover: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAbsorbBadDebtCoverInstructionAsync(input),
            ),
          acknowledgeMultiplier: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAcknowledgeMultiplierInstructionAsync(input),
            ),
          borrow: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getBorrowInstructionAsync(input),
            ),
          createMarket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateMarketInstructionAsync(input),
            ),
          depositCollateral: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositCollateralInstructionAsync(input),
            ),
          initializeConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeConfigInstructionAsync(input),
            ),
          liquidate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getLiquidateInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          markLiquidatable: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getMarkLiquidatableInstructionAsync(input),
            ),
          openPosition: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenPositionInstructionAsync(input),
            ),
          openSupplier: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenSupplierInstructionAsync(input),
            ),
          payBackerInterest: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPayBackerInterestInstructionAsync(input),
            ),
          pushPrice: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPushPriceInstructionAsync(input),
            ),
          repay: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRepayInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          setAdmin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetAdminInstructionAsync(input),
            ),
          setFallbackGrace: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetFallbackGraceInstructionAsync(input),
            ),
          setFeedAuthority: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetFeedAuthorityInstructionAsync(input),
            ),
          setPaused: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPausedInstructionAsync(input),
            ),
          setPayoutAddress: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPayoutAddressInstructionAsync(input),
            ),
          setPoolLiquidator: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPoolLiquidatorInstructionAsync(input),
            ),
          supply: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSupplyInstructionAsync(input),
            ),
          syncIssuerState: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSyncIssuerStateInstructionAsync(input),
            ),
          updateMarketParams: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateMarketParamsInstructionAsync(input),
            ),
          withdrawCollateral: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawCollateralInstructionAsync(input),
            ),
          withdrawSupply: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawSupplyInstructionAsync(input),
            ),
          writeDownCollateral: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWriteDownCollateralInstructionAsync(input),
            ),
        },
        pdas: {
          usdcVault: findUsdcVaultPda,
          config: findConfigPda,
          position: findPositionPda,
          market: findMarketPda,
          collateralVault: findCollateralVaultPda,
          supplier: findSupplierPda,
        },
        identifyAccount: identifyStockVaultAccount,
        identifyInstruction: identifyStockVaultInstruction,
        parseInstruction: parseStockVaultInstruction,
      } as StockVaultPlugin,
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
